char *infin_mod_second(char *divided, char* divisor, int negative_case)
{
    char one[] = "-1";
    char *division = infin_div(divided, divisor);
    char *mult = infin_mul(division, divisor);
    char *sub = malloc(sizeof(char) * (my_strlen(mult) + 2));

