        divisor[0] = '0';
    reverse_string(divided, divisor);
    for (i = my_strlen(divisor); divisor[i - 1] == '0'; i--);
    divisor[i] = '\0';
    for (i = my_strlen(divided); divided[i - 1] == '0'; i--);
    divided[i] = '\0';
    reverse_string(divided, divisor);
    return (infin_mod_second(divided, divisor, negative_case));
