char *selection_sub(char string_three[], int r, int i, int negative_case)
{
    if (r == 0)
        i = i - 1;
    if (negative_case == 0) {
        i = i - 1;
        string_three[i + 1] = '\0';
        for (i; string_three[i] == '0' && i > 0; i--);
        string_three[i + 1] = '-';
        string_three[i + 2] = '\0';
    } else {
        for ((i + 1); string_three[i] == '0' && i > 0; i--);
        string_three[i + 1] = '\0';
    }
    my_revstr(string_three);
    if (string_three[0] == '-' && string_three[1] ==
        '0' && string_three[2] == '\0')
        return ("0");
    return (string_three);
