#include <limits.h>

int my_compute_power_rec(int nb, int p)
{
    int b = 0;

    if (nb * nb > INT_MAX)
        return (0);
    if (p <= 1) {
        if (p == 0)
            return (1);
        if (p < 0)
            return (0);
        if (p == 1)
            return (nb);
    } else {
        b = nb * my_compute_power_rec(nb, p - 1);
        return (b);
    }
}

